from pathlib import Path
import json,re,hashlib,datetime
B=Path(__file__).resolve().parent
S=B/'source/common/src/main/java/com/telepathicgrunt/the_bumblezone'
def save(n,x):(B/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
s=(S/'client/rendering/armor/BeeArmorModel.java').read_text();results={}
for variant in [1,2]:
 chunk=s.split(f'public static LayerDefinition createVariant{variant}()')[1].split('return LayerDefinition.create')[0]
 parts=[]
 for stmt in chunk.split(';'):
  m=re.search(r'(\w+)\.addOrReplaceChild\("([^"\n]+)"',stmt)
  if not m:continue
  boxes=[]
  for t in re.finditer(r'\.texOffs\(([^)]+)\)\.addBox\(([^)]+), new CubeDeformation\(([^)]+)\)\)',stmt):
   nums=[float(v.strip().rstrip('Ff')) for v in t.group(2).split(',')]
   boxes.append({'uv_origin':[float(v.strip()) for v in t.group(1).split(',')],'origin':nums[:3],'dimensions':nums[3:],'deformation':float(t.group(3).strip().rstrip('Ff'))})
  pose=re.search(r'PartPose\.(offsetAndRotation|offset)\(([^)]+)\)',stmt)
  parts.append({'parent_variable':m[1],'part_name':m[2],'boxes':boxes,'pose':{'kind':pose[1],'values':[float(v.strip().rstrip('Ff')) for v in pose[2].split(',')]} if pose else None})
 results[f'variant_{variant}']={'explicit_replaced_parts':parts,'explicit_box_count':sum(len(p['boxes']) for p in parts),'plane_count':sum(0 in b['dimensions'] for p in parts for b in p['boxes']),'atlas':[128,128],'not_included':'Inherited HumanoidModel mesh and exact MC1.20.6 Cube baking/face projection are not derived here; declarations are not final UV/pose proof.'}
save('explicit-model-declarations.json',results)
slots=[('HEAD','stingless_bee_helmet_1'),('CHEST','bumble_bee_chestplate_1'),('LEGS','honey_bee_leggings_1'),('FEET','carpenter_bee_boots_1')]
save('four-slot-source-binding.json',{'fixed_commit':'727844606bf41de151af9ae71e82caeaa72d04ce','minecraft':'1.20.6','loader':'NeoForge20.6.82-beta (source declared; not launched)','mod_version':'7.5.3','scope':'normal variant1, unpollinated ground state; variant2 atlas/model read only for distinguishing number semantics, not a second design','slots':[{'slot':s,'id':'the_bumblezone:'+n,'item_model':f'common/src/main/resources/assets/the_bumblezone/models/item/{n}.json','provider':'new BeeArmorModelProvider per registered item','worn_texture':'the_bumblezone:textures/models/armor/bee_material_layer_1.png','worn_layer':'BeeArmorModel.createVariant1 / 128x128'} for s,n in slots],'state_rules':{'leggings':'pollen property: zero -> base-only model; one -> base plus pollen overlay; worn true legs with optional pollen children','boots':'base plus two tiny gold overlay pixels, no armor tint handler proven or presumed','chest':'wings change rotations with flying component; zero-thickness segmented planes. No motion measured','texture_number':'item getVariant, NOT LEGS selector. Non-trans selected; trans palette excluded','visibility':'renderToBuffer fixed slot: HEAD renders head subtree only; CHEST body subtree only; LEGS true legs with pollen state and boots false; FEET boots true and true legs false. Inherited arms/hat must not be assumed visible from flags alone.'},'consumer_chain':['BumblezoneClient listener registration and registerArmorProviders creates provider per item','NeoForge getGenericArmorModel -> ForgeArmorProviders.get -> one-time RegisterArmorProviderEvent -> provider.getFinalModel','getFinalModel copies vanilla model properties and visibility; BeeArmorModel render method overrides slot visibility','getModel bakes createVariant1 and caches slot-bound BeeArmorModel; sets variant before getArmorTexture filename uses it','BzArmorMixin getArmorTexture delegates; runtime ordering/mixin application still unverified','NeoForge RegisterLayerDefinitions event -> RegisterEntityLayersEvent -> two BeeArmorModel suppliers'],'pending':['No full bootstrap/mixin config and actual NeoForge runtime ordering validation','Exact MC1.20.6 face UV orientation, inherited mesh, mirror and final seams unverified','Native acquisition/repair tag origin and real crafting/payment not verified','No game five views, silhouette, worn visuals or flight/pollen state run']})
old=Path('docs/art/armor-arctic-whole-20261114/combined-semantic-ledger.json').resolve();ledger=json.loads(old.read_text())
