assert not any(k.startswith('the_bumblezone:') for k in ledger['reviewed_case_keys'])
review={'batch':'D87','status':'NEW_FIXED_SOURCE_DESIGN_STUDIED_PENDING_INDEPENDENT_SEMANTIC_ACCEPTANCE','whole_key':key,'whole_slots':4,'new_validated_credit':0,'new_learning_groups':0,'candidate_designs_for_review':1,'counts_not_designs':{'pinned_files':48,'native_images_viewed':8,'variants_counted':1,'slots_counted_as_designs':False},'requirements':{'global_sha256':sha(B/'global-texture-requirements.txt'),'project_sha256':sha(B/'project-texture-requirements.txt'),'target_scope':'Priority armor icons/worn UV; research only, no priority target has both never-redrawn+crude proof','production':False},'observations':['头盔图标保留紧凑倒U开口，黄额和两侧黑颊清楚；穿戴头罩10×9×12及两组触角是昆虫专属结构，不能照搬到普通人类布皮甲。','胸图标由横向金黄/棕带和两侧白翼辨认；穿戴以9.01×8×5.01下胸、7×2×5和5×2×5上胸分层，材质带替代密集纹样。两翼由各9片零厚度阶梯平面组成，不是假球面或高模。','裤图标为短腰连接两条黑直腿；少量黄腰带和膝侧点避免整腿涂亮。花粉状态另有两个黄色矩形覆盖，不把状态或overlay算额外设计。','靴图标为直筒黑短靴、少量金扣和清楚分开的两脚；实穿variant1靴盒6×5×7更宽并带2³扣块，不按图标反推原版UV。','128²图集以黑棕和黄块分区，黄色含细碎蜂毛纹理；对Dynasty普通布皮优先学暗底/边口大区，不照抄毛纹或增加高频噪点。','variant2头罩明显变浅、胸盒改单体且翼UV不同，作为同主题结构变体排除额外信用；trans配色、花粉状态与四部位均不拆计。'],'semantic_dedup':{'old_same_namespace_case':None,'old_related_case':'terra_equipment:bee','old_related_review':'docs/art/armor-local-complete-reference-20261104/semantic-review.json','old_observation':'蜂甲黄棕大带、细胸，八名称共用基础盔口/V胸/直裤/短靴保守归原版材料模板。','new_distinction':'本套实际新来源，头罩触角、独立阶梯翼、两层真腿/靴节点和花粉袋状态组成完整用途相关结构；仅是候选独立设计，不能因命名空间不同直接获信用。','overlap_to_review':['Prior Thermal beekeeper is protective veil suit, not native insect wing/pollen anatomy','Prior Terra bee color bands may overlap; full old whole visuals not re-opened this batch, independent comparison pending'],'accepted_new_credit':0},'limits':['Only normalvariant1 four slot images and two overlays studied; variant2 atlas viewed to prevent layer misbinding','Other downloaded variant2/trans icons not claimed visually reviewed','No source asset copied into Dynasty production','Global accepted applicable 1000 total/gap unknown; gate remains false','No build or game needed for research; no task removed']}
save('semantic-review.json',review)
ledger['current_batch_prior']={'path':str(old),'sha256':sha(old)}
ledger['reviewed_pending_whole_keys'].append(key)
ledger['pending_whole_families'].append({'primary_whole_key':key,'review':str(B/'semantic-review.json'),'sha256':sha(B/'semantic-review.json'),'already_recorded_case':None,'whole_slots':4,'new_learning_groups':0,'new_validated_credit':0,'pending':review['limits']+['Independent semantic novelty/applicability and full fixed-source consumer acceptance pending']})
